-- ===================================================================================
-- DYNAMIC CAMPAIGN REPORTER (generated by BriefingRoom)
-- Writes the state of every objective to dcs.log, so the result can be uploaded
-- back to BriefingRoom to advance the dynamic campaign. Line format:
-- BRDC|token|sequence|missionTime|missionComplete|playerAircraftLost|dead/total/complete,...
-- ===================================================================================

briefingRoom.dynamicCampaign = { }
briefingRoom.dynamicCampaign.token = "$TOKEN$"
briefingRoom.dynamicCampaign.sequence = 0
briefingRoom.dynamicCampaign.dead = { } -- unit names reported dead by events
briefingRoom.dynamicCampaign.tracked = { } -- unit names that existed at mission start
briefingRoom.dynamicCampaign.playerLost = { } -- player aircraft lost (unit names)
briefingRoom.dynamicCampaign.playerLostCount = 0

local function brdcSafeName(object)
  if object == nil then return nil end
  local ok, name = pcall(function() return object:getName() end)
  if ok then return name end
  return nil
end

local function brdcFindObject(name)
  local unit = Unit.getByName(name)
  if unit ~= nil then return unit end
  return StaticObject.getByName(name)
end

local function brdcIsDead(name)
  if briefingRoom.dynamicCampaign.dead[name] then return true end
  local object = brdcFindObject(name)
  if object == nil then return true end
  local ok, alive = pcall(function() return object:isExist() and object:getLife() >= 1 end)
  if not ok then return true end
  return not alive
end

function briefingRoom.dynamicCampaign.report()
  local dc = briefingRoom.dynamicCampaign
  dc.sequence = dc.sequence + 1
  local objectivesText = { }
  for i, objective in ipairs(briefingRoom.mission.objectives) do
    local dead = 0
    local total = 0
    for _, name in ipairs(objective.unitNames or { }) do
      if dc.tracked[name] then
        total = total + 1
        if brdcIsDead(name) then dead = dead + 1 end
      end
    end
    local complete = 0
    if objective.complete and not objective.failed then complete = 1 end
    table.insert(objectivesText, dead.."/"..total.."/"..complete)
  end
  local missionComplete = 0
  if briefingRoom.mission.complete then missionComplete = 1 end
  env.info("BRDC|"..dc.token.."|"..dc.sequence.."|"..string.format("%.0f", timer.getTime()).."|"..missionComplete.."|"..dc.playerLostCount.."|"..table.concat(objectivesText, ","), false)
end

local function brdcMarkPlayerLost(unit)
  if unit == nil then return end
  local ok, playerName = pcall(function() return unit:getPlayerName() end)
  if not ok or playerName == nil then return end
  local okCoalition, coalitionId = pcall(function() return unit:getCoalition() end)
  if not okCoalition or coalitionId ~= briefingRoom.playerCoalition then return end
  local name = brdcSafeName(unit)
  if name == nil or briefingRoom.dynamicCampaign.playerLost[name] then return end
  briefingRoom.dynamicCampaign.playerLost[name] = true
  briefingRoom.dynamicCampaign.playerLostCount = briefingRoom.dynamicCampaign.playerLostCount + 1
end

briefingRoom.dynamicCampaign.eventHandler = { }
function briefingRoom.dynamicCampaign.eventHandler:onEvent(event)
  if event == nil then return end
  if event.id == world.event.S_EVENT_DEAD or event.id == world.event.S_EVENT_CRASH or event.id == world.event.S_EVENT_UNIT_LOST then
    local name = brdcSafeName(event.initiator)
    if name ~= nil then briefingRoom.dynamicCampaign.dead[name] = true end
  end
  if event.id == world.event.S_EVENT_KILL then
    local name = brdcSafeName(event.target)
    if name ~= nil then briefingRoom.dynamicCampaign.dead[name] = true end
  end
  if event.id == world.event.S_EVENT_CRASH or event.id == world.event.S_EVENT_EJECTION or event.id == world.event.S_EVENT_PILOT_DEAD then
    brdcMarkPlayerLost(event.initiator)
  end
  if event.id == world.event.S_EVENT_MISSION_END then
    briefingRoom.dynamicCampaign.report()
  end
end

function briefingRoom.dynamicCampaign.start()
  local dc = briefingRoom.dynamicCampaign
  for _, objective in ipairs(briefingRoom.mission.objectives) do
    for _, name in ipairs(objective.unitNames or { }) do
      if brdcFindObject(name) ~= nil then dc.tracked[name] = true end
    end
  end
  world.addEventHandler(dc.eventHandler)

  -- Report again whenever an objective is completed
  local completeObjective = briefingRoom.mission.coreFunctions.completeObjective
  briefingRoom.mission.coreFunctions.completeObjective = function(index, failed)
    completeObjective(index, failed)
    pcall(briefingRoom.dynamicCampaign.report)
  end

  dc.report()
  timer.scheduleFunction(function(_, time)
    pcall(briefingRoom.dynamicCampaign.report)
    return time + 60
  end, nil, timer.getTime() + 60)
end

timer.scheduleFunction(function() briefingRoom.dynamicCampaign.start() end, nil, timer.getTime() + 2)
